    <link rel="icon" href="https://bookworldlibrary.com/wp-content/uploads/2025/12/cropped-fav-32x32.png" sizes="32x32">
    <style>
        :root {
            --wp--preset--color--base: #f9f9f9;
            --wp--preset--color--base-2: #ffffff;
            --wp--preset--color--contrast: #111111;
            --wp--preset--color--contrast-2: #636363;
            --wp--preset--font-size--small: 0.9rem;
            --wp--preset--font-size--medium: 1.05rem;
            --wp--preset--font-size--large: clamp(1.39rem, 1.39rem + ((1vw - 0.2rem) * 0.767), 1.85rem);
            --wp--preset--font-size--x-large: clamp(1.85rem, 1.85rem + ((1vw - 0.2rem) * 1.083), 2.5rem);
            --wp--preset--font-size--xx-large: clamp(2.5rem, 2.5rem + ((1vw - 0.2rem) * 1.283), 3.27rem);
            --wp--preset--font-family--system-sans-serif: -apple-system, BlinkMacSystemFont, avenir next, avenir, segoe ui, helvetica neue, helvetica, Cantarell, Ubuntu, roboto, noto, arial, sans-serif;
            --wp--preset--spacing--20: min(1.5rem, 2vw);
            --wp--preset--spacing--30: min(2.5rem, 3vw);
            --wp--preset--spacing--40: min(4rem, 5vw);
            --wp--preset--spacing--50: min(6.5rem, 8vw);
            --wp--preset--spacing--60: min(10.5rem, 13vw);
            --wp--preset--spacing--10: 1rem;
            --wp--preset--shadow--natural: 6px 6px 9px rgba(0, 0, 0, 0.2);
            --wp--preset--shadow--deep: 12px 12px 50px rgba(0, 0, 0, 0.4);
            --wp--style--global--content-size: 620px;
            --wp--style--global--wide-size: 1280px;
            --wp--style--block-gap: 1.2rem;
            --wp--style--root--padding-top: 0px;
            --wp--style--root--padding-right: var(--wp--preset--spacing--50);
            --wp--style--root--padding-bottom: 0px;
            --wp--style--root--padding-left: var(--wp--preset--spacing--50);
        }
        * {
            box-sizing: border-box;
        }
        :where(body) {
            margin: 0;
        }
        body {
            background-color: var(--wp--preset--color--base);
            color: var(--wp--preset--color--contrast);
            font-family: var(--wp--preset--font-family--system-sans-serif);
            font-size: var(--wp--preset--font-size--medium);
            font-weight: 400;
            line-height: 1.55;
        }
        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
            color: var(--wp--preset--color--contrast);
            font-family: var(--wp--preset--font-family--system-sans-serif);
            font-weight: 400;
            line-height: 1.2;
        }
        a {
            color: var(--wp--preset--color--base-2);
        }
        img {
            height: auto;
            max-width: 100%;
            vertical-align: bottom;
        }
        figure {
            margin: 0;
        }
        .wp-site-blocks {
            padding-top: var(--wp--style--root--padding-top);
            padding-bottom: var(--wp--style--root--padding-bottom);
        }
        .has-global-padding {
            padding-right: var(--wp--style--root--padding-right);
            padding-left: var(--wp--style--root--padding-left);
        }
        .has-global-padding>.alignfull {
            margin-right: calc(var(--wp--style--root--padding-right) * -1);
            margin-left: calc(var(--wp--style--root--padding-left) * -1);
        }
        .is-layout-constrained> :where(:not(.alignleft):not(.alignright):not(.alignfull)) {
            max-width: var(--wp--style--global--content-size);
            margin-left: auto !important;
            margin-right: auto !important;
        }
        .is-layout-constrained>.alignwide {
            max-width: var(--wp--style--global--wide-size);
        }
        .is-layout-constrained>.alignfull {
            max-width: 100%;
        }
        .is-layout-flow>* {
            margin-block-start: var(--wp--style--block-gap);
            margin-block-end: 0;
        }
        .is-layout-flow> :first-child {
            margin-block-start: 0;
        }
        .is-layout-flow> :last-child {
            margin-block-end: 0;
        }
        .is-layout-flex {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            gap: var(--wp--style--block-gap);
        }
        .is-layout-flex>* {
            margin: 0;
        }
        body .is-layout-flex {
            display: flex;
        }
        .has-text-align-center {
            text-align: center;
        }
        .has-medium-font-size {
            font-size: var(--wp--preset--font-size--medium) !important;
        }
        .has-large-font-size {
            font-size: var(--wp--preset--font-size--large) !important;
        }
        .has-x-large-font-size {
            font-size: var(--wp--preset--font-size--x-large) !important;
        }
        .has-xx-large-font-size {
            font-size: var(--wp--preset--font-size--xx-large) !important;
        }
        .has-base-2-color {
            color: var(--wp--preset--color--base-2) !important;
        }
        .has-contrast-2-color {
            color: var(--wp--preset--color--contrast-2) !important;
        }
        mark.has-inline-color {
            background: none;
        }
        /* Countdown sticky */
        .ip-countdown-sticky {
            position: sticky;
            top: 0;
            z-index: 9999;
            padding: 12px 15px;
            box-shadow: 0 2px 20px rgba(0, 0, 0, 0.15);
            width: 100%;
            box-sizing: border-box;
            text-align: center;
            border-bottom: 1px solid rgba(0, 0, 0, 0.2);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 6px;
        }
        .countdown-label {
            color: #fff;
            font-family: Arial, sans-serif;
            font-size: 14px;
            font-weight: bold;
            letter-spacing: 0.5px;
            margin: 0;
        }
        .countdown-cards {
            display: inline-flex;
            align-items: flex-start;
            flex-wrap: nowrap;
            gap: 0;
        }
        .time-group {
            display: inline-block;
            text-align: center;
            margin: 0 2px;
            vertical-align: top;
        }
        .time-card {
            background-color: #ffffff;
            color: #000000;
            font-size: 22px;
            font-family: Arial, sans-serif;
            padding: 4px 10px;
            border-radius: 4px;
            margin: 0 1px;
            border: 1px solid #000000;
            display: inline-block;
            font-weight: bold;
            line-height: 1;
            vertical-align: top;
        }
        .time-separator {
            font-size: 22px;
            font-family: Arial, sans-serif;
            color: #ffffff;
            font-weight: bold;
            margin: 0 4px;
            display: inline-block;
            vertical-align: top;
            line-height: 1;
            padding-top: 4px;
        }
        .time-label {
            display: block;
            font-size: 13px;
            font-family: Arial, sans-serif;
            color: #ffffff;
            font-style: italic;
            margin-top: 4px;
            line-height: 1;
            text-align: center;
        }
        @media (max-width: 480px) {
            .time-card {
                font-size: 18px;
                padding: 3px 7px;
            }
            .time-separator {
                font-size: 18px;
            }
            .time-label {
                font-size: 11px;
            }
        }
        /* Buttons */
        :where(.wp-element-button, .wp-block-button__link) {
            background-color: #01bc00;
            border-radius: 20px;
            border: 0;
            color: #ffffff;
            font-family: var(--wp--preset--font-family--system-sans-serif);
            font-size: var(--wp--preset--font-size--medium);
            font-weight: 500;
            padding-top: 0.6rem;
            padding-right: 1rem;
            padding-bottom: 0.6rem;
            padding-left: 1rem;
            text-decoration: none;
            cursor: pointer;
        }
        .wp-block-buttons {
            display: flex;
            flex-wrap: wrap;
            box-sizing: border-box;
        }
        .wp-block-buttons.is-content-justification-center {
            justify-content: center;
        }
        .wp-block-buttons>.wp-block-button {
            display: inline-block;
            margin: 0;
        }
        .wp-block-button__link {
            display: inline-block;
            text-align: center;
            word-break: break-word;
            box-shadow: var(--wp--preset--shadow--deep);
        }
