            width: 75%;
        }
        .wp-block-buttons>.wp-block-button.has-custom-width .wp-block-button__link {
            width: 100%;
        }
        :where(.wp-block-button__link) {
            border-radius: 9999px;
            padding: calc(.667em + 2px) calc(1.333em + 2px);
            text-decoration: none;
        }
        /* Images */
        .wp-block-image img {
            width: 100%;
            height: auto;
        }
        .wp-block-image.alignfull img,
        .wp-block-image.aligncenter img {
            width: 100%;
            height: auto;
        }
        .alignfull {
            width: 100%;
            max-width: 100%;
        }
        .aligncenter {
            text-align: center;
            margin-left: auto;
            margin-right: auto;
        }
        /* Separator */
        .wp-block-separator {
            border: none;
            border-top: 1px solid;
            width: 100%;
        }
        .wp-block-separator.is-style-wide {
            width: 100%;
        }
        .wp-block-separator.has-alpha-channel-opacity {
            opacity: 0.4;
        }
        /* Spacer */
        .wp-block-spacer {
            clear: both;
        }
        /* Group */
        .wp-block-group {
            box-sizing: border-box;
        }
        /* Gallery */
        .wp-block-gallery.has-nested-images {
            display: flex;
            flex-wrap: wrap;
            align-items: normal;
        }
        .wp-block-gallery.has-nested-images figure.wp-block-image {
            box-sizing: border-box;
            display: flex;
            flex-direction: column;
            flex-grow: 1;
            justify-content: center;
            max-width: 100%;
            width: 100%;
        }
        .wp-block-gallery.has-nested-images figure.wp-block-image img {
            display: block;
            height: auto;
            width: 100%;
        }
        .wp-block-gallery-2 {
            gap: var(--wp--preset--spacing--10) 0;
        }
        /* Columns */
        .wp-block-columns {
            box-sizing: border-box;
            display: flex;
            flex-wrap: wrap !important;
            margin-bottom: 1.75em;
        }
        @media (min-width: 782px) {
            .wp-block-columns {
                flex-wrap: nowrap !important;
            }
        }
        .wp-block-column {
            flex-grow: 1;
            min-width: 0;
            overflow-wrap: break-word;
            word-break: break-word;
        }
        @media (max-width: 781px) {
            .wp-block-columns>.wp-block-column {
                flex-basis: 100% !important;
            }
        }
        /* ===== MOBILE FIXES ===== */
        html,
        body {
            overflow-x: hidden !important;
        }
        @media (max-width: 768px) {
            body {
                --wp--style--root--padding-right: 0px !important;
                --wp--style--root--padding-left: 0px !important;
                max-width: 100vw !important;
            }
            .wp-site-blocks,
            main.wp-block-group {
                padding-left: 0 !important;
                padding-right: 0 !important;
                max-width: 100vw !important;
                overflow-x: hidden !important;
            }
            .entry-content.wp-block-post-content {
                padding-left: 16px !important;
                padding-right: 16px !important;
                box-sizing: border-box !important;
                max-width: 100vw !important;
                overflow-x: hidden !important;
            }
            /* alignfull images borda a borda */
            .wp-block-image.alignfull,
            figure.wp-block-image.alignfull {
                margin-left: -16px !important;
                margin-right: -16px !important;
                width: calc(100% + 32px) !important;
                max-width: calc(100% + 32px) !important;
                box-sizing: border-box !important;
            }
            .wp-block-image.alignfull img,
            figure.wp-block-image.alignfull img,
            .wp-block-image img {
                width: 100% !important;
                height: auto !important;
                display: block !important;
                max-width: 100% !important;
            }
            /* Gallery full width */
            figure.wp-block-image.aligncenter,
            figure.wp-block-image.alignfull {
                margin-left: -16px !important;
                margin-right: -16px !important;
                width: calc(100% + 32px) !important;
            }
            figure.wp-block-image.aligncenter img,
            figure.wp-block-image.alignfull img {
                width: 100% !important;
                height: auto !important;
            }
            /* Font scaling */
            .has-x-large-font-size {
                font-size: 1.4rem !important;
            }
            .has-xx-large-font-size {
                font-size: 1.6rem !important;
            }
            .has-large-font-size {
                font-size: 1.2rem !important;
            }
            /* Remove excess margins */
            p[style*="margin-right:var(--wp--preset--spacing--60)"],
            p[style*="margin-left:var(--wp--preset--spacing--60)"],
            p[style*="margin-right:var(--wp--preset--spacing--50)"],
            p[style*="margin-left:var(--wp--preset--spacing--50)"] {
                margin-right: 0 !important;
                margin-left: 0 !important;
            }
            p[style*="padding-right:var(--wp--preset--spacing--40)"],
            p[style*="padding-left:var(--wp--preset--spacing--40)"],
            p[style*="padding-right:var(--wp--preset--spacing--50)"],
            p[style*="padding-left:var(--wp--preset--spacing--50)"] {
                padding-right: 0 !important;
                padding-left: 0 !important;
            }
            /* Button full width */
            .wp-block-button.has-custom-width.wp-block-button__width-75 {
                width: 100% !important;
            }
            .wp-block-button__link {
                width: 100% !important;
                font-size: 1.1rem !important;
                padding: 14px 20px !important;
                box-sizing: border-box !important;
            }
            /* Footer stacked */
            .wp-block-columns[style*="flex-wrap:nowrap"] {
                flex-wrap: wrap !important;
            }
            .wp-block-column[style*="flex-basis:30%"],
            .wp-block-column[style*="flex-basis:50%"] {
                flex-basis: 100% !important;
                text-align: center;
            }
            .wp-block-navigation__container {
                flex-direction: column;
                align-items: center;
            }
        }
        /* ===== END MOBILE FIXES ===== */
        /* Navigation */
        .wp-block-navigation__container {
            list-style: none;
            padding: 0;
            margin: 0;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
        }
        .wp-block-navigation-item__content {
            color: var(--wp--preset--color--contrast);
            text-decoration: none;
        }
        .wp-block-navigation-item__content:hover {
            text-decoration: underline;
        }
        /* Site title / tagline */
        .wp-block-site-title {
            font-size: clamp(0.875rem, 0.875rem + ((1vw - 0.2rem) * 0.542), 1.2rem);
            font-weight: 600;
        }
        .wp-block-site-title a {
            text-decoration: none;
            color: inherit;
        }
        .wp-block-site-tagline {
            color: var(--wp--preset--color--contrast-2);
            font-size: var(--wp--preset--font-size--small);
        }
        /* Footer */
        footer .wp-block-group {
            padding-top: var(--wp--preset--spacing--50);
            padding-bottom: var(--wp--preset--spacing--50);
        }
        /* Container group inner layout */
        .wp-container-core-group-is-layout-5a338822>* {
            margin-block-start: 0;
            margin-block-end: 0;
        }
        .wp-container-core-group-is-layout-5a338822>*+* {
            margin-block-start: var(--wp--preset--spacing--30);
            margin-block-end: 0;
        }
        /* Post content */
        .wp-block-post-content {
            display: flow-root;
        }
        .emoji {
            display: inline !important;
            border: none !important;
            box-shadow: none !important;
            height: 1em !important;
            width: 1em !important;
            margin: 0 0.07em !important;
