            /* 2. TOTAL CATCH-ALL: Center EVERYTHING by default unless Full-Width */
            .entry-content.wp-block-post-content > *:not(.alignfull):not(.alignwide) {
                max-width: 800px !important;
                margin-left: auto !important;
                margin-right: auto !important;
                padding-left: 20px !important;
                padding-right: 20px !important;
                box-sizing: border-box !important;
            }
            /* 3. Unleash pure full-width sections */
            .entry-content.wp-block-post-content > .alignfull, 
