                width: 100% !important;
                max-width: 100% !important;
                margin-left: 0 !important;
                margin-right: 0 !important;
            }
            /* 4. Recursive nested element constraint to keep interior contents centered */
            .entry-content.wp-block-post-content .wp-block-group.alignfull > *:not(.wp-block-image):not(.alignfull) {
                 max-width: 800px !important;
                 margin-left: auto !important;
                 margin-right: auto !important;
                 padding-left: 20px !important;
                 padding-right: 20px !important;
                 box-sizing: border-box !important;
            }
            /* 5. Preserve nested full-width images inside special sections */
            .entry-content.wp-block-post-content .wp-block-group.alignfull figure.wp-block-image,
            .entry-content.wp-block-post-content .wp-block-group.alignfull figure.wp-block-image img {
                 max-width: 100% !important;
                 width: 100% !important;
            }
            /* 6. Finalize standard layout boundaries */
